local BackpackCellNode = Class('BackpackCellNode')

function BackpackCellNode:__init()
    self.data = nil
    self.cb = nil
    self.catTips = nil
    self.catTipHeadTrans = nil
end

function BackpackCellNode:__delete()
    self.data = nil
    self.cb = nil
    self.catTips = nil
    self.catTipHeadTrans = nil
end

function BackpackCellNode:Awake()
    self.catTips = self.ImgSelect.transform.parent:Find("CardTip")
    self.catTipHeadTrans = self.ImgSelect.transform.parent:Find("CardTip/Worn/MaskHead/ImgRoleHead")
end

function BackpackCellNode:SetCallback(cb)
    self.cb = cb
end

---FreshUI
---@param data table
---@param position number
---@param isSelected boolean 是否是选中关状态
---@param isSell boolean 是否是出售状态
function BackpackCellNode:FreshUI(data, position, isSelected, isSell)
    if isNull(self.GoodNode) then
        self.GoodNode = self.GoodNodeStub:InstantiatePrefab("GoodNode")
        local rect = self.GoodNode.gameObject:GetComponent("RectTransform")
        rect.pivot = Vector2.New(0.5, 0.5)
        rect.anchoredPosition = Vector3.New(0, 0, 0)
        rect.anchorMax = Vector2.New(0.5, 0.5)
        rect.anchorMin = Vector2.New(0.5, 0.5)
        
        KTool.SetActive(self.GoodNode.gameObject, true)
    end 

    local reScale = self.GoodNode.gameObject:GetComponent(typeof(ReverseScale))
    reScale.scale = 0.75
    reScale:ResetScale()
    local goodNodeMB = GetLuaBehaviour(self.GoodNode.gameObject, GoodsNodeMBPath)
    if not IsNull(goodNodeMB) then
        if IsNull(goodNodeMB.Env) then
            goodNodeMB:Init()
        end
        ---@type GoodNodeMB
        local env = goodNodeMB.Env
        local numItem = data.num -- 物品数量
        numItem = numItem >= 100000 and "99999+" or tostring(numItem) -- 数量显示
        local goodType = GoodsUtils.GetIdType(data.goodsId)
        if goodType == Constants.IDType.Equipment then
            env:Reload(
                    {
                        goodsId = data.goodsId,
                        text = numItem,
                        isShowNo = true,
                        dojo = data.vo
                    }
            )
            ---@type EquipDojo
            local dojo = data.vo
            if self.catTips then
                KTool.SetActive(self.catTips, checkNumber(dojo.playerCardId) > 0)
            end
            --if checkNumber(dojo.playerCardId) > 0 then
                -----@type CardComponent
                --local cardComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
                --local cardDojo = cardComp:GetCardById(dojo.playerCardId)
                --local cardVo = CardConfMgr:GetInstance():GetCardByRefId(cardDojo.cardId) ---然后取初始的皮肤 然后取头像等
                -----@type CardSkinVo
                --local skinVo = CardConfMgr:GetInstance():GetCardSkinBySkinId(cardVo.defaultSkin)
                --if self.catTipHeadTrans then
                --    CfUtils.FillImage(self.catTipHeadTrans, skinVo.buffHead)
                --end
            --end
            env:RefreshEquippedShowState(checkNumber(dojo.playerCardId) > 0)

        else
            if self.catTips then
                KTool.SetActive(self.catTips, false)
            end
            env:Reload(
                    {
                        goodsId = data.goodsId,
                        text = numItem,
                        isShowNo = true,
                    }
            )
        end

        env:SetClickCallback(function()
            if self.cb then
                self.cb(data, position)
            end
        end)
    end
    
    local goodsType = GoodsUtils.GetIdType(data.goodsId)
    
    -- 装备刻印单独处理
    if goodsType == Constants.IDType.Equipment then
        if checkInt(data.vo.bindPlayerCardId) > 0 then
            CfUtils.SetActive(self.CultivateOverseaEquipEngraveHead, true)
            local cardProgressionConstants = import("Game.CardProgression.CardProgressionConstants")
            local scr = CfUtils.GetLuaScr(self.CultivateOverseaEquipEngraveHead, cardProgressionConstants.EnvPath.EquipmentEngraveNode)
            if isNotNull(scr) then
                scr:RefreshNode(data.vo)
            end
        else
            CfUtils.SetActive(self.CultivateOverseaEquipEngraveHead, false)
        end
    else
        CfUtils.SetActive(self.CultivateOverseaEquipEngraveHead, false)
    end
    
    CfUtils.SetActive(self.Quantity, checkBool(isSell))
    CfUtils.SetActive(self.ImgSelect, checkBool(isSelected))

    local hasRedPoint = backpackComponent:IsBackpackGoodsIdRedPoint(data.goodsId)
    CfUtils.SetActive(self.redPoint, checkBool(hasRedPoint))
end

function BackpackCellNode:FreshBatchSellTxt(text)
    CfUtils.FillText(self.TextNumber, text)
end

function BackpackCellNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return BackpackCellNode